window.VTMB=window.VTMB||{};window.VTMB.advText={"v5-linguistics":{"f":"You speak more than your mother tongue and the local language.","e":"One extra language per dot: you speak, read and write it fluently."},"v5-illiterate":{"f":"You never learned to read or write.","e":"Academics and Science are capped at 1, and you can’t take specialties in them that need modern knowledge."},"v5-repulsive":{"f":"Something about your looks makes people recoil.","e":"Lose two dice from Social pools where appearance matters."},"v5-ugly":{"f":"You are unpleasant to look at.","e":"Lose one die from Social pools where appearance matters."},"v5-beautiful":{"f":"You are striking, and people notice.","e":"Add one die to Social pools where appearance matters."},"v5-stunning":{"f":"Your beauty stops conversations.","e":"Add two dice to Social pools where appearance matters."},"v5-hopeless-addiction":{"f":"You are hooked on a drug, and you can only get it through your victims’ blood.","e":"Lose two dice from all pools when your last vessel wasn’t on your drug, except pools to get the drug right now."},"v5-addiction":{"f":"You crave a drug you can only get through your victims’ blood.","e":"Lose one die from all pools when your last vessel wasn’t on your drug, except pools to get the drug right now."},"v5-high-functioning-addict":{"f":"The drug in your vessels’ blood sharpens you instead of dulling you.","e":"Add one die to one category of pools (chosen with the drug) when your last vessel was on it."},"v5-archaic":{"f":"The modern world left you behind, perhaps while you slept in torpor.","e":"You can’t use computers or phones and Technology stays at 0. The Storyteller may take a die from pools involving modern tech."},"v5-living-in-the-past":{"f":"You cling to the morals of another century.","e":"Take one or more outdated Convictions. Lose one die from Social pools where they show, except with Kindred your age or older."},"v5-bondslave":{"f":"Vampire Blood owns you the moment it touches your tongue.","e":"A single drink of another vampire’s Blood binds you fully, instead of three."},"v5-bond-junkie":{"f":"The Blood Bond feels too good to fight.","e":"Lose one die from pools to act against a Blood Bond."},"v5-long-bond":{"f":"Bonds fade from you slowly.","e":"A Blood Bond on you weakens by one step only every three months without reinforcement."},"v5-bond-resistance":{"f":"Your Blood fights against being enslaved.","e":"Add one die per dot to resist a Blood Bond."},"v5-short-bond":{"f":"Bonds slip off you quickly.","e":"A Blood Bond on you weakens by two steps each month (at full and new moon) without reinforcement."},"v5-unbondable":{"f":"No vampire can own you through Blood.","e":"You can never be Blood Bound."},"v5-farmer":{"f":"You swore off human blood.","e":"You feed only on animals. Drinking human blood costs two Willpower. Not for Ventrue."},"v5-organovore":{"f":"Blood alone doesn’t satisfy you; you need flesh.","e":"You slake Hunger only by eating human flesh and blood-rich organs. Only the heart carries Resonance."},"v5-methuselahs-thirst":{"f":"Mortal blood no longer fills you.","e":"Only the blood of supernatural creatures can bring your Hunger below 1."},"v5-prey-exclusion":{"f":"There are people you refuse to feed on.","e":"Name a type of prey. Feeding on them gives you Stains as if you broke a chronicle Tenet."},"v5-bloodhound":{"f":"You can smell what a person’s blood will taste like.","e":"Sense a human’s Resonance by scent alone with Resolve + Awareness (Difficulty 3)."},"v5-iron-gullet":{"f":"You can keep down blood that would make others retch.","e":"Feed on cold, rancid or bagged blood and plasma, though it carries no Resonance. Not for Ventrue."},"v5-stake-bait":{"f":"The old stories about stakes are true for you.","e":"A stake through the heart destroys you instead of sending you into torpor."},"v5-folkloric-bane":{"f":"Something from folklore can truly hurt you.","e":"Pick a bane: UV light, silver or holy water. It deals you Aggravated damage."},"v5-folkloric-block":{"f":"Something from folklore holds you back.","e":"Pick a block (holy symbols, running water, uninvited thresholds, garlic…). Spend a Willpower to push past it, or shrink away."},"v5-stigmata":{"f":"You bleed like a martyr when the Hunger rises.","e":"At Hunger 4 you bleed from your hands, feet and brow: it draws attention and leaves traces."},"v5-eat-food":{"f":"You can still sit down to dinner.","e":"Eat and even enjoy food. It gives no nourishment, and you must bring it up before day-sleep."},"v5-baby-teeth":{"f":"You never grew proper fangs.","e":"You can’t bite to feed: you need a blade or a syringe."},"v5-bestial-temper":{"f":"Your Beast is as strong as a true vampire’s.","e":"You must test for frenzy like any other vampire."},"v5-branded-by-the-camarilla":{"f":"The Camarilla marked you with a brand that never heals.","e":"The Sheriff’s people watch you and wait for you to step out of line."},"v5-clan-curse-thin-blood":{"f":"A trace of your sire’s curse lives in your Blood.","e":"Pick a clan bane and suffer it at Bane Severity 1 (Brujah or Gangrel need Bestial Temper, Tremere needs Catenating Blood)."},"v5-dead-flesh":{"f":"Your weak Blood can’t stop your body from rotting.","e":"You look and smell dead: lose a die on face-to-face Social tests with mortals. Can’t take Lifelike."},"v5-mortal-frailty":{"f":"Your Blood won’t heal you.","e":"You can’t Rouse the Blood to mend; you heal like a mortal. Can’t take Vampiric Resilience."},"v5-shunned-by-the-anarchs":{"f":"You crossed the Anarchs, and they remember.","e":"Local Anarchs would rather hand you to the Camarilla than help you. Can’t take Anarch Comrades."},"v5-vitae-dependency":{"f":"Your powers run on stolen vampire Blood.","e":"Unless you slake one Hunger with vampire Blood each week, you can’t use any Disciplines or Alchemy."},"v5-anarch-comrades":{"f":"An Anarch coterie has taken you under their wing.","e":"They act as a one-dot Anarch Mawla, as long as you toe the line."},"v5-camarilla-contact":{"f":"A Camarilla recruiter promised to make you a real vampire.","e":"You have a one-dot Camarilla Mawla who treats you badly and expects you to spy."},"v5-catenating-blood":{"f":"Your Blood is thick enough to make others like you.","e":"You can Blood Bond and Embrace like a full vampire. Your childer are thin-bloods."},"v5-day-drinker":{"f":"The sun weakens you instead of burning you.","e":"In sunlight your Health is halved and you lose your vampiric powers, but you take no other damage."},"v5-discipline-affinity":{"f":"One Discipline comes naturally to you.","e":"Gain one dot in a Discipline of your choice and raise it with experience at out-of-clan cost."},"v5-lifelike":{"f":"You still pass for the living.","e":"You have a heartbeat, can eat, and pass all but the most advanced medical exams."},"v5-thin-blood-alchemist":{"f":"You’ve learned to cook your Blood into potent formulas.","e":"Gain one dot and one formula of Thin-Blood Alchemy."},"v5-vampiric-resilience":{"f":"Your body is tough like a true vampire’s.","e":"Bullets and blades deal you Superficial damage, as to any vampire."},"v5-allies":{"f":"Mortals who help you because they want to: friends, family, or an organization that owes you.","e":"Build an Ally (or group) from up to six dots: Effectiveness from 1 (weak mortal) to 4 (deadly or gifted with magic), plus Reliability from 1 (shows up half the time) to 3. They appear about once a story."},"v5-contacts":{"f":"Mortals in the right places who know things and can get things.","e":"Each Contact trades information and favors in their field. Buy several for different fields.","lv":{"1":"Can get something cheap or common (Resources 1): a weed dealer, a car salesman.","2":"Can get something useful (Resources 2): a small-time gun dealer, a vet.","3":"Can get something expensive or hard (Resources 4): a security expert, a homicide lieutenant."}},"v5-fame":{"f":"Mortals know your name and follow what you do.","e":"Each dot lowers the Difficulty of Social tests against fans and of many hunting tests by one. You may use Fame in place of a Trait to get into exclusive places. Harder to stay unnoticed.","lv":{"1":"A select subculture knows and admires you.","2":"A local celebrity, recognised across much of the city.","3":"Most people in the country know your name.","4":"Anyone who follows trends or your field knows about you.","5":"National or global fame: a movie star, a stadium act, a former president."}},"v5-infamy":{"f":"You are famous for something horrible.","e":"Reaction tests against you get harder by the Flaw’s rating; at worst, the authorities try to kill or capture you on sight."},"v5-dark-secret":{"f":"You did something terrible, and only you and a few motivated enemies know.","e":"If it comes out, you’d gain Infamy one dot higher than this Flaw.","lv":{"1":"You owe a big debt to bad people, or someone close to you is infamous.","2":"You’re a Cleaver, a serial Masquerade breacher, Blood Hunted elsewhere, or you offended this domain’s ruler."}},"v5-influence":{"f":"Pull in the mortal world through money, office, prestige or blackmail.","e":"Works fully in one group or region of the city and one dot lower citywide. The Storyteller may let you roll it in place of a Trait to sway officials.","lv":{"1":"Well-connected: you’re guaranteed a respectful hearing.","2":"Influential: people want to do you favors.","3":"Entrenched: power-brokers hesitate to oppose you.","4":"Powerful: functionaries obey without a good reason not to.","5":"Dominant: lesser figures guess what you want and do it first."}},"v5-despised":{"f":"One group or part of the city lives to thwart you.","e":"Lose two dice when trying to win neutral parties’ political support or favors."},"v5-disliked":{"f":"The city doesn’t like you much.","e":"Lose one die on Social tests with any group in the city except your Contacts, Allies and other loyal supporters."},"v5-haven":{"f":"A resting place that’s safer, bigger and more private than a blacked-out flat.","e":"Each dot adds +1 to the Difficulty of finding, entering or watching it, and one die to notice danger while you’re there.","lv":{"1":"Small but secure: a basement flat, a crypt, a locked storeroom.","2":"Good size, security or privacy: a house, a branch sewer tunnel.","3":"Very large, secure or private: a compound, a bank, a disused subway station."}},"v5-no-haven":{"f":"You have nowhere to sleep.","e":"Every morning you must find a new resting place, with at least a basic test."},"v5-compromised":{"f":"Your haven has been raided before and is on someone’s watchlist.","e":"Intruders and spies add two dice to break in or watch it."},"v5-creepy":{"f":"Your haven looks like a serial killer’s den.","e":"Lose two dice on Social tests to seduce or relax human guests there, and neighbors may tip off the police."},"v5-haunted":{"f":"Something supernatural lives in your haven, and you don’t control it.","e":"At least one die of penalty per dot to affected pools in the haven; whoever understands it can use it against you."},"v5-hidden-armory":{"f":"Weapons stashed where no one will find them.","e":"Each dot: one pistol and one long gun with ammunition, as hidden as your resting place."},"v5-cell":{"f":"A locked room for prisoners.","e":"Holds two prisoners at escape Difficulty 5. Each extra dot doubles the capacity or adds +1 to the Difficulty. Not in small havens."},"v5-watchmen":{"f":"Armed guards watch your haven.","e":"Each dot: four Average guards and one Gifted boss."},"v5-laboratory":{"f":"A real lab in your haven.","e":"Each dot adds one die to one Science or Technology specialty, or to Fixatio alchemy. Not in small havens."},"v5-library":{"f":"A collection of occult texts, city histories or vampire lore.","e":"Each dot adds one die to research with one Academics, Investigation or Occult specialty. Small havens: one dot at most."},"v5-location":{"f":"Your haven sits somewhere prime: an exclusive district, a private island, the Rack.","e":"Add two dice to the bonuses from either your Chasse or your base Haven rating (pick one)."},"v5-luxury":{"f":"Designer furniture, art and expensive toys fill your haven.","e":"Add two dice to Social tests with mortal guests there. Without Resources 3, it was gained illegally."},"v5-postern":{"f":"A back way out: a hidden exit, a tunnel, a grate into the sewers.","e":"Each dot adds one die to evade or escape surveillance near your haven."},"v5-security-system":{"f":"Alarms, cameras and locks better than most.","e":"Each dot adds one die to resist, or be alerted to, intruders in your haven."},"v5-surgery":{"f":"A room equipped as a field surgery.","e":"Add two dice to Medicine and similar tests in your haven. Not in small havens."},"v5-warding":{"f":"A magical ward keeps supernatural things out of your haven.","e":"Each dot adds one die to resist scrying, and blocks whatever else you agree with the Storyteller. May need Occult 3 or Blood Sorcery."},"v5-herd":{"f":"A group of mortals you can feed on without hunting.","e":"Slake Hunger equal to your Herd rating each week without a roll. Overfeeding thins the Herd.","lv":{"1":"One to three vessels, random Resonance; once a month you can shift one’s Resonance.","2":"Four to seven vessels, half of them sharing one Resonance you choose.","3":"Seven to fifteen vessels with two Resonances, chosen each week.","4":"Sixteen to thirty vessels, two Resonances a week; keeping them takes some effort.","5":"Thirty-one to sixty vessels, three Resonances a week; it starts to strain the Masquerade."}},"v5-obvious-predator":{"f":"Humans sense the predator in you.","e":"Lose two dice from hunting pools (except pure stalking, chasing and killing) and one die from Social tests to put humans at ease. You can’t keep a Herd."},"v5-mask":{"f":"A fake identity good enough to live a mortal life on paper.","e":"Without it you only have ID that survives a traffic stop.","lv":{"1":"A full false identity with bank account and records; passes a regional background check.","2":"Passes a national police check; your old military or intelligence record is classified."}},"v5-known-blankbody":{"f":"Intelligence agencies have you flagged as a possible terrorist.","e":"Your biometrics and aliases sit in several databases, and any inquisitor will recognise you as a vampire."},"v5-known-corpse":{"f":"People know you died recently.","e":"Those who knew you react with shock and horror if they see you, and database checks show you as dead."},"v5-zeroed":{"f":"Someone powerful wiped your real records.","e":"You officially don’t exist. Needs Mask 2."},"v5-cobbler":{"f":"You make fake identities for others.","e":"Make a Mask in three days per dot (with some online risk), or source one in a day per dot for a price. Needs Mask 2."},"v5-mawla":{"f":"A Kindred patron or mentor who looks out for you, for a price.","e":"They offer advice, information and occasional help, and expect favours back. A group of Mawali costs one dot more.","lv":{"1":"A neonate.","2":"An ancilla.","3":"An elder.","4":"A Primogen or Anarch council member.","5":"A Prince or Baron."}},"v5-adversary":{"f":"A Kindred who wants you, or someone you’re tied to, brought down.","e":"From a one-dot elder to a three-dot Prince or cabal. They act against you with their own Traits."},"v5-resources":{"f":"Money, property and assets that keep your unlife comfortable.","e":"Define where the income comes from; it can dry up or be taken.","lv":{"1":"Paycheck to paycheck: a flat, a car, camping gear.","2":"Middle class: a nice flat or small house, several cars, good equipment.","3":"Rich: a great condo or house, luxuries, gear for several people.","4":"Wealthy: a mansion, a helicopter or private jet, specialist equipment.","5":"Ultra rich: many mansions, anything money can buy."}},"v5-destitute":{"f":"You have nothing.","e":"No money and no home."},"v5-retainers":{"f":"A loyal servant: a ghoul, a dominated thrall, a devoted lover.","e":"You must keep them controlled with money, Blood or mesmerism. Buy several for more servants.","lv":{"1":"An underwhelming helper without a Blood Bond: build as a Weak mortal.","2":"A ghoul, servant, lover or thrall: an Average mortal or a ghoul without Advantages.","3":"A competent retainer who acts on their own: a ghoul as good as a Gifted mortal."}},"v5-stalkers":{"f":"People get a little too attached to you.","e":"A former retainer or admirer keeps trying to reconnect. Get rid of them and another soon appears."},"v5-status":{"f":"Standing among the Kindred of your sect in this city.","e":"The Storyteller may add it to Social pools at court or let it stand in for a Social Trait. Worth one dot less in another city; none in another sect. Caitiff can’t buy it at creation.","lv":{"1":"Known: a properly introduced neonate, an up-and-comer.","2":"Respected: you have responsibilities, like an average ancilla.","3":"Influential: authority over part of the sect, like an average elder.","4":"Powerful: you hold office, such as Sheriff, Harpy or Scourge.","5":"Luminary: you sit at the table of power, among the Primogen."}},"v5-shunned":{"f":"A sect loathes you: you betrayed them or crossed their leaders.","e":"Its members actively work against you whenever they can."},"v5-suspect":{"f":"You broke an oath or weaseled out of a boon, and a sect hasn’t forgotten.","e":"Lose two dice on Social tests involving that faction until you make amends."},"v5-enemies":{"f":"Mortals who work against you.","e":"Built like Allies, but worth two dots less than their Effectiveness as a Flaw.","lv":{"1":"A Gifted mortal, or a dangerous group of Average ones.","2":"A deadly mortal, a magic user, or a well-armed group of Gifted mortals."}},"v5-minor-boon":{"f":"Another Kindred owes you a small favour.","e":"Costs half (rounded up) of a Mawla of the same rank: the higher the debtor stands, the more it costs. Creation only."},"v5-business-establishment":{"f":"A business runs out of your haven: a café, a call centre, a salon.","e":"Counts roughly as Resources of the same rating and adds two dice to things related to the business. Your haven loses a dot of privacy or security."},"v5-furcus":{"f":"Your haven sits on a knot of mystic power.","e":"Each dot adds one die to Blood Sorcery Rituals (or Oblivion Ceremonies) there, but failures there can go horribly wrong."},"v5-machine-shop":{"f":"A fully equipped workshop with tools and supplies.","e":"Each dot adds one die to building, repairing or taking apart machines. Small havens: one Craft specialty only."},"v5-shared":{"f":"Your haven isn’t entirely yours.","e":"Other Kindred can use it and make decisions about it.","lv":{"1":"Housemates or a temporary safe house; their problems become yours.","2":"A Kindred landlord who can walk in at will and may call on you for service."}},"v5-city-secrets":{"f":"You know something damning about the city’s Kindred power structure.","e":"Those who want it kept quiet have reason to keep you happy, or to silence you. The Storyteller may add it to Social or research pools. Take up to three times."},"v5-famous-face":{"f":"You look just like someone famous.","e":"Add two dice where you can use the resemblance; lose two dice when trying to blend into a crowd."},"v5-ing-nue":{"f":"You look completely innocent.","e":"Add two dice to avoid suspicion or deflect blame."},"v5-remarkable-feature":{"f":"Something about you is unforgettable: striking eyes, an unusual complexion.","e":"Add two dice to Social tests with strangers (the novelty wears off); lose one die to disguise yourself."},"v5-vessel-recognition":{"f":"You can smell when a mortal belongs to someone else’s herd.","e":"With Resolve + Awareness (Difficulty 2), tell whether a mortal was fed on recently; a critical win shows if it happens regularly."},"v5-luck-of-the-devil":{"f":"Someone else always takes the fall for you.","e":"Once per session, redirect a misfortune aimed at you (an attack, an accusation) onto someone close to you."},"v5-check-the-trunk":{"f":"You keep a cache of tools and junk for any job.","e":"Easy access to gear worth up to Resources 2, and two extra dice on Preparedness tests for such items."},"v5-side-hustler":{"f":"You always know someone who knows someone.","e":"Once per session, get an item, a piece of information or access as if you had two dots in the right Resources, Contacts or Influence."},"v5-tempered-will":{"f":"Your stubborn will survived the Embrace.","e":"You always know when Dominate or Presence is used on you, and once per session add two dice to resist them. Only if you have neither Discipline."},"v5-untouchable":{"f":"The powers that be won’t punish you, whatever you do.","e":"Once per story, escape all official punishment for a crime that should destroy or exile you."},"v5-transparent":{"f":"You are a terrible liar.","e":"Lose one die from Subterfuge pools, and you can never raise Subterfuge."},"v5-vein-tapper":{"f":"Feeding is too private to do in front of anyone.","e":"You can’t feed on mortals while being watched; you seek out unconscious or drugged victims."},"v5-starving-decay":{"f":"Only feeding keeps your body from rotting.","e":"At Hunger 3 or more you shrivel: lose two dice on Physical tests and Social tests with mortals, and risk the Masquerade."},"v5-twice-cursed":{"f":"Your founder’s curse weighs twice as heavily on you.","e":"Suffer your clan’s Players Guide variant bane as well as your regular bane."},"v5-knowledge-hungry":{"f":"You burn to learn everything about one subject.","e":"Whenever you could learn about it, make a Willpower roll (Difficulty 3) to resist chasing it."},"v5-prestation-debts":{"f":"You owe minor boons to a more powerful Kindred.","e":"You owe two minor boons; your creditor gets one die in Social combat against you and calls them in at the worst time."},"v5-risk-taker":{"f":"You can’t pass up a new thrill.","e":"Facing a risky temptation you haven’t tried, lose two dice on everything until you indulge or the scene ends."},"v5-weak-willed":{"f":"Other people’s wills overpower yours.","e":"Lose one die on Social pools against a leader or superior, and you can’t actively resist Dominate or Presence."},"v5-favored-blood":{"f":"Your Blood answers to no Antediluvian’s curse.","e":"Learn any Discipline without having tasted the Blood of someone who has it. Not with Muddled Blood."},"v5-mark-of-caine":{"f":"You bear a mark that gives other vampires pause.","e":"Add two dice to intimidate Kindred who believe in Caine. Diablerists can’t add Blood Potency against you, and any failure is bestial."},"v5-mockingbird":{"f":"You can copy the powers of those you drink from.","e":"After drinking a Hunger’s worth from a vampire, use one of their Discipline powers for a night (up to your highest Discipline level), and suffer their bane too."},"v5-sun-scarred":{"f":"You are one of the rare Daywalkers.","e":"The first turn in sunlight costs one Aggravated Willpower instead of Health; for the rest of the scene sunlight deals only Superficial damage."},"v5-uncle-fangs":{"f":"Local thin-bloods look up to you.","e":"A coterie of three to five thin-bloods acts as your Ally group and can supply alchemy. Not with Liquidator."},"v5-befouling-vitae":{"f":"Your Blood turns victims into ravenous corpses.","e":"Anyone you Embrace or kill by feeding rises within nights as a hungry wight."},"v5-clan-curse":{"f":"Your sire’s clan curse still clings to you.","e":"Suffer one clan bane of your choice at half Bane Severity (minimum 1)."},"v5-debt-peon":{"f":"You are in the pocket of a powerful Kindred, and you’ll never get out.","e":"You owe them boons they keep renewing; they get two dice in Social combat against you in public. Refusing makes you Shunned."},"v5-liquidator":{"f":"Thin-bloods know you as one of the Camarilla’s hunters.","e":"Lose two dice on Social pools (except Intimidation) against thin-bloods. Not with Uncle Fangs."},"v5-muddled-blood":{"f":"Your Blood forgets its own power.","e":"To raise any Discipline, even one you have, you must first drink the Blood of someone who has it. Not with Favored Blood."},"v5-walking-omen":{"f":"Every prophecy in the city points at you.","e":"Scrying and omens in your domain name you as a source of disaster; expect at least one serious clash per story."},"v5-word-scarred":{"f":"Ancient vampiric lore is written across your skin.","e":"The chronicle’s great occult power keeps trying to capture or erase you, and anyone who reads you learns a terrible secret."},"v5-heliophobia":{"f":"You fear the sun as much as a true vampire does.","e":"Sunlight can drive you into terror frenzy."},"v5-night-terrors":{"f":"The dreams you forget by day come back at night.","e":"Once per session nightmares break through: lose one die on everything for the rest of the scene."},"v5-plague-bearer":{"f":"You still catch mortal diseases, and pass them on.","e":"Roll a die per Hunger slaked; any 1 means you caught something. Only slaking to Hunger 0 cures it."},"v5-sloppy-drinker":{"f":"Your bite is messy.","e":"Make Dexterity + Medicine (Difficulty = Hunger slaked) to close the wound; fail and the victim may bleed out."},"v5-sun-faded":{"f":"Daylight shuts down your powers.","e":"No Disciplines or Alchemy in sunlight; indoors by day they work at a two-dice penalty."},"v5-supernatural-tell":{"f":"Other supernatural beings can sense you.","e":"Lose two dice from Stealth and similar pools against supernatural opponents, vampires included."},"v5-twilight-presence":{"f":"Something about you makes everyone uneasy.","e":"Lose one die from Social pools with anyone but thin-bloods."},"v5-unending-hunger":{"f":"Small sips never satisfy you.","e":"Once per scene of feeding, you slake one less Hunger."},"v5-abhorrent-blood":{"f":"Your Blood makes other vampires gag.","e":"Vampires who bite you must stop, or spend two Willpower a turn to keep drinking."},"v5-faith-proof":{"f":"You’re too close to mortal to be touched by faith.","e":"True Faith has no effect on you."},"v5-low-appetite":{"f":"Your Hunger rises slowly.","e":"At Hunger 0 or 1, and when waking, roll two dice for Rouse Checks and keep the best."},"v5-lucid-dreamer":{"f":"You still dream, and you remember.","e":"Once per session after day-sleep, ask the Storyteller for a clue or hint revealed in a dream."},"v5-mortalitys-mien":{"f":"Your aura still looks human.","e":"Powers that detect the supernatural see you as mortal; add two dice to pass as mortal in other ways."},"v5-swift-feeder":{"f":"You feed quickly and cleanly.","e":"Once per scene, slake one Hunger in a single turn, wound licked closed."},"v5-unseemly-aura":{"f":"The Blood made your aura look like a vampire’s.","e":"Aura-reading powers see you as one of the Kindred."},"v5-baneful-blood":{"f":"You carry a trace of your first domitor’s clan bane.","e":"Suffer their bane at one level per dot (Lasombra, Malkavian, Ministry, Nosferatu, Ravnos, Salubri or Toreador domitors only)."},"v5-death-proof":{"f":"Oblivion slides off you.","e":"You are immune to Oblivion but can never learn it."},"v5-major-boon":{"f":"Another Kindred owes you a serious favour.","e":"Costs one dot more than a Minor Boon from the same Kindred. Creation only.","lv":{"2":"Owed by a neonate or ancilla.","3":"Owed by an elder, Primogen or Anarch council member.","4":"Owed by a Prince or Baron."}},"v5-minor-debt":{"f":"You owe another Kindred a small favour.","e":"They can call it in when it suits them. The higher their standing, the more the Flaw is worth."},"v5-major-debt":{"f":"You owe another Kindred a serious favour.","e":"Once per story your creditor can demand a favour you can’t refuse without being shunned or Blood Hunted."},"v5-life-debt":{"f":"You owe another Kindred your unlife.","e":"They can demand almost anything of you, and refusing could see you destroyed."},"v20-acute-sense":{"f":"One of your senses is exceptionally sharp.","e":"Pick a sense: tasks using it are at −2 difficulty. Stacks with Auspex."},"v20-bruiser":{"f":"You look like a thug, and people cross the street to avoid you.","e":"Intimidation is at −1 difficulty against anyone who hasn’t proven themselves physically stronger than you."},"v20-early-riser":{"f":"You need less rest than other vampires.","e":"You always wake as if your Humanity were 10, first up at dusk. Not with Deep Sleeper."},"v20-friendly-face":{"f":"Your face reminds everyone of someone they like.","e":"Friendly Social rolls with strangers are at −1 difficulty on a first meeting."},"v20-enchanting-voice":{"f":"People can’t ignore your voice.","e":"Rolls that use your voice to persuade, charm or command are at −2 difficulty."},"v20-daredevil":{"f":"You take wild risks, and survive them.","e":"Add three dice and cancel one botch die on very dangerous non-combat stunts."},"v20-efficient-digestion":{"f":"You get more out of every drink.","e":"Gain one extra blood point for every two you drink (up to your maximum)."},"v20-hard-of-hearing":{"f":"Your hearing is poor.","e":"Hearing-based rolls are at +2 difficulty."},"v20-smell-of-the-grave":{"f":"You smell of damp earth and fresh graves, and no perfume covers it.","e":"Lose one die from Social pools where scent matters, and two from Stealth pools against anyone who can smell you, unless you’re upwind."},"v20-tic-twitch":{"f":"Under stress you have a telltale habit.","e":"A nervous tic gives you away; resisting it costs one Willpower."},"v20-bad-sight":{"f":"Your eyesight is poor.","e":"Sight-based rolls are at +2 difficulty. At one point glasses fix it; at three nothing does."},"v20-disfigured":{"f":"A hideous disfigurement makes you disturbing and memorable.","e":"Social rolls are at +2 difficulty, and Appearance can’t go above 2."},"v20-dulled-bite":{"f":"Your fangs never grew in properly.","e":"You need another way to open a vein, or twice the usual successes to bite."},"v20-infectious-bite":{"f":"Your bite festers.","e":"You can’t lick wounds closed, and one bite in five makes the victim seriously ill."},"v20-one-eye":{"f":"You have only one eye.","e":"Sight-based Perception is at +2 difficulty; anything needing depth perception (ranged combat too) at +1."},"v20-vulnerability-to-silver":{"f":"Silver burns you like sunlight.","e":"Silver weapons deal aggravated damage, and touching silver is painful."},"v20-open-wound":{"f":"A wound on you never heals and never stops bleeding.","e":"Lose an extra blood point each night; +1 difficulty to Social rolls if it shows. At four points it also counts as Permanent Wound."},"v20-child":{"f":"You were Embraced as a small child.","e":"Strength and Stamina max 2 at creation, and +2 difficulty to lead mortal adults. Take Small as well."},"v20-deformity":{"f":"A misshapen limb, a hunched back or a clubfoot.","e":"The Storyteller sets the penalties, for example −2 Dexterity and +1 difficulty to Social rolls."},"v20-glowing-eyes":{"f":"Your eyes glow like a vampire’s in the old films.","e":"−1 difficulty to intimidate mortals, but +1 to sight-based rolls and +2 to hide in the dark, and you must always disguise them."},"v20-lazy":{"f":"You avoid any effort you can.","e":"You’re often unprepared; spontaneous Physical actions, unplanned fights included, are at +1 difficulty."},"v20-monstrous":{"f":"The Embrace twisted you into the image of your Beast.","e":"You look like a savage monster: Appearance 0. Not for clans that already have Appearance 0."},"v20-slow-healing":{"f":"Your wounds close slowly.","e":"Healing bashing or lethal damage costs two blood points per level; aggravated damage takes five days per level."},"v20-disease-carrier":{"f":"A lethal, contagious disease lives in your blood.","e":"Spend an extra blood point each night or show symptoms. Vampires who drink from you may catch it."},"v20-flesh-of-the-corpse":{"f":"Your body heals, but the damage stays visible.","e":"Cuts, holes and tears never fade, making social dealings hard and wearing down your Appearance."},"v20-infertile-vitae":{"f":"Your Blood can’t make new vampires.","e":"Anyone you try to Embrace dies. You can still make ghouls and use your Blood in rituals."},"v20-introspection":{"f":"You understand your own motives, and so other people’s.","e":"Add two dice to Perception against someone with the same Nature or Demeanor as you."},"v20-time-sense":{"f":"You always know what time it is.","e":"You can judge the passage of time accurately without a watch."},"v20-useful-knowledge":{"f":"You know something that interests an older vampire.","e":"As long as your expertise holds their attention, they act like a one-dot Mawla."},"v20-code-of-honor":{"f":"You live by a strict personal code.","e":"Add two dice to Willpower and Virtue rolls when acting by your code or avoiding having to break it."},"v20-computer-aptitude":{"f":"Computers come naturally to you.","e":"All rolls involving computers are at −2 difficulty."},"v20-light-sleeper":{"f":"You wake instantly at any sign of danger.","e":"Ignore the dice limits on acting during the day."},"v20-natural-linguist":{"f":"You have a gift for languages.","e":"Add three dice to anything involving languages, and each dot of Linguistics gives you two languages instead of one."},"v20-calm-heart":{"f":"You are naturally calm and slow to anger.","e":"Add two dice to resist frenzy. Not for Brujah."},"v20-precocious":{"f":"You learn quickly.","e":"Learning a Skill takes half the time and half the experience."},"v20-deep-sleeper":{"f":"You sleep like the dead, even for a vampire.","e":"Rolls to wake during the day are at +2 difficulty."},"v20-impatient":{"f":"You can’t stand waiting.","e":"Whenever you’re made to wait, roll Self-Control or rush off on your own."},"v20-shy":{"f":"You are ill at ease with people.","e":"Social rolls with strangers are at +2 difficulty, +3 when you’re the centre of attention."},"v20-soft-hearted":{"f":"You can’t bear to watch others suffer.","e":"Causing anyone pain requires a Willpower roll (difficulty 8). Needs Humanity 7 or higher."},"v20-speech-impediment":{"f":"You stammer or otherwise struggle to speak.","e":"Rolls involving speech are at +2 difficulty."},"v20-unconvinced":{"f":"You openly doubt your sect’s or clan’s beliefs.","e":"Your superiors suspect you, and your enemies have noticed."},"v20-lunacy":{"f":"The moon stirs your Beast.","e":"Frenzy difficulties rise by one under a crescent moon, two under a half or gibbous moon, and three under a full moon."},"v20-short-fuse":{"f":"You anger easily.","e":"Frenzy difficulties are two higher. Not for Brujah."},"v20-stereotype":{"f":"You act like a vampire from the movies: capes, accents, theatrics.","e":"+2 difficulty to Social rolls with Kindred who don’t share your style, and hunters spot you easily."},"v20-territorial":{"f":"You claim a hunting ground and defend it savagely.","e":"When another vampire enters it uninvited, check for frenzy or attack them. You hate to leave it."},"v20-thirst-for-innocence":{"f":"Innocence makes you ravenous.","e":"On seeing innocence, roll Self-Control or Instincts, or frenzy and attack."},"v20-victim-of-the-masquerade":{"f":"You refuse to believe you’re a vampire.","e":"You keep searching for a logical explanation, struggle to feed, and try to eat food. Must be roleplayed."},"v20-conspicuous-consumption":{"f":"You must eat your victims’ hearts and livers too.","e":"Feeding usually kills; take Eat Food as well."},"v20-guilt-wracked":{"f":"Every feeding fills you with guilt.","e":"Roll Conscience (difficulty 7) each time you feed or frenzy, so you avoid feeding and run low on blood."},"v20-flashbacks":{"f":"A past trauma throws you off balance without warning.","e":"At the start of each story roll Willpower; fail, and your Willpower counts as 1 for the session."},"v20-elysium-regular":{"f":"You spend most nights in Elysium.","e":"Its movers and shakers, the Harpies included, know your name."},"v20-former-ghoul":{"f":"You served as a ghoul long before your Embrace.","e":"−1 difficulty on Social rolls with untaught neonates and on rolls about vampire lore."},"v20-harmless":{"f":"Everyone knows you’re no threat.","e":"Nobody thinks you’re worth killing, until you prove otherwise."},"v20-natural-leader":{"f":"Others naturally defer to you.","e":"Add two dice to Leadership. Needs Charisma 3."},"v20-prestigious-sire":{"f":"Your sire is, or was, someone important.","e":"Their name opens doors with other vampires, or breeds jealousy."},"v20-prot-g":{"f":"Your sire spoke highly of you before your Embrace.","e":"−1 difficulty on Social rolls with those who’ve heard the praise."},"v20-rep":{"f":"Your name is known beyond your sect.","e":"Everyone has heard of what you did, or are said to have done, for good or ill."},"v20-sabbat-survivor":{"f":"You survived a Sabbat attack or recruitment.","e":"−1 difficulty on Perception rolls about the Sabbat, such as spotting their ambushes."},"v20-bullyboy":{"f":"The Sheriff or Bishop calls on you when they need muscle.","e":"You get in on action others miss, win favour with those in power and sometimes act above the law."},"v20-old-pal":{"f":"A friend from life was Embraced alongside you.","e":"They act as a very loyal Ally, and expect the same of you."},"v20-lawmans-friend":{"f":"The Sheriff likes you.","e":"They overlook your small offences and warn you about crackdowns, as long as you don’t abuse it."},"v20-open-road":{"f":"You travel often and know how to do it safely.","e":"You know safe routes and havens, and can travel between cities without random trouble."},"v20-sanctity":{"f":"Everyone sees you as pure and innocent.","e":"You are trusted and liked, and tend to get lighter punishments."},"v20-scholar-of-enemies":{"f":"You’ve studied one of your sect’s enemies closely.","e":"−2 difficulty on non-combat rolls about that enemy, +1 about other enemies."},"v20-scholar-of-others":{"f":"You’ve studied one other group closely.","e":"−2 difficulty on non-combat rolls about that group, +1 about others."},"v20-friend-of-the-underground":{"f":"You know the tunnels and sewers, and their Nosferatu tolerate you.","e":"−1 difficulty on rolls involving the underground. Not for Nosferatu."},"v20-mole":{"f":"You have a spy inside an enemy group.","e":"They feed you information about what their side is planning."},"v20-rising-star":{"f":"You are your sect’s rising star.","e":"−1 difficulty on Social rolls with sect members who aren’t working against you."},"v20-broken-bond":{"f":"You secretly broke a Blood Bond.","e":"Your regnant still thinks you are bound. You may never be bound again. Not for Sabbat."},"v20-clan-friendship":{"f":"Another clan likes you.","e":"−2 difficulty on friendly Social rolls with its members. Your own clan may not approve."},"v20-primogen-bishop-friendship":{"f":"The city’s rulers value your opinion.","e":"You are consulted on decisions, and your advice carries weight."},"v20-botched-presentation":{"f":"You made a fool of yourself when presented to the Prince.","e":"Make a Willpower roll (difficulty 7) to face the Prince or their officials without falling apart. Camarilla only."},"v20-expendable":{"f":"Someone in power wants you gone.","e":"They keep sending you into danger “for the good of the sect”."},"v20-incomplete-understanding":{"f":"You still don’t really get how your sect works.","e":"Sooner or later you’ll break a rule you didn’t understand."},"v20-infamous-sire":{"f":"Your sire is distrusted across the city.","e":"Their bad name rubs off on you."},"v20-mistaken-identity":{"f":"You look like another Kindred, one with a reputation.","e":"People keep mistaking you for them, sometimes dangerously."},"v20-new-arrival":{"f":"You’ve just arrived in the city and know no one.","e":"Factions try to recruit or remove you, and your ignorance of local politics invites blunders."},"v20-new-kid":{"f":"You are the newest neonate in town, and everyone knows it.","e":"+1 difficulty on Social rolls with other neonates; elders don’t take you seriously."},"v20-recruitment-target":{"f":"An enemy of your sect wants you, badly.","e":"They keep trying to recruit you, willing or not, at the worst moments."},"v20-sires-resentment":{"f":"Your sire hates you.","e":"They and their allies work against you whenever they can."},"v20-special-responsibility":{"f":"You volunteered for a thankless duty, and now you’re stuck with it.","e":"You get no credit for doing it and lose respect if you stop."},"v20-sympathizer":{"f":"You’ve spoken up for your sect’s enemies.","e":"The city’s rulers suspect you of treason."},"v20-bound":{"f":"You are Blood Bound to another vampire.","e":"Your will isn’t entirely your own. Not for Sabbat."},"v20-catspaw":{"f":"You did someone powerful’s dirty work, and now you’re a liability.","e":"They want you quiet now, and gone later."},"v20-escaped-target":{"f":"Someone else Embraced the mortal you’d chosen.","e":"+2 difficulty to resist frenzy around your rival, and +1 to Charisma rolls until it’s resolved."},"v20-failure":{"f":"You once held office and failed spectacularly.","e":"You are branded incompetent, shut out of power, and suspected of disloyalty."},"v20-masquerade-breaker":{"f":"You broke the Masquerade once, and someone covered for you.","e":"They hold it over you and use you mercilessly."},"v20-hunted":{"f":"A fanatical hunter is after you.","e":"They pursue you and anyone close to you."},"v20-old-flame":{"f":"Someone you loved now works for the enemy.","e":"You can’t act against them unless you win Manipulation + Expression against them, or your life is at stake."},"v20-rival-sires":{"f":"Two vampires wanted to Embrace you; the loser holds a grudge.","e":"They are at +2 difficulty to resist frenzy around you and work to discredit you."},"v20-uppity":{"f":"You bragged too loudly and made enemies.","e":"+2 difficulty on Social rolls against those you offended, and you may need Willpower to stop boasting."},"v20-disgrace-to-the-blood":{"f":"Your sire calls your Embrace a mistake, publicly.","e":"You are mocked, your petitions ignored and your achievements dismissed."},"v20-former-prince":{"f":"You once ruled a city.","e":"The local Prince fears a comeback and stacks the deck against you. Camarilla only."},"v20-hunted-like-a-dog":{"f":"A sect or group of vampires wants you destroyed.","e":"They hunt you relentlessly, though their enemies may help you."},"v20-narc":{"f":"Everyone knows you inform for the powers that be.","e":"+1 difficulty on Social rolls with those who don’t share your politics; they feed you lies."},"v20-sleeping-with-the-enemy":{"f":"You are close to someone on the other side.","e":"If your sect finds out, it’s treason, and death."},"v20-clan-enmity":{"f":"An entire clan wants you dead.","e":"+2 difficulty on Social rolls with its members, who snub, insult or attack you."},"v20-loathsome-regnant":{"f":"You are Blood Bound to a master who abuses you.","e":"Your unlife under the Bond is a nightmare. Not for Sabbat."},"v20-overextended":{"f":"You control too much, and people have noticed.","e":"Rivals work to cut you down and block any new expansion."},"v20-probationary-sect-member":{"f":"You defected from another sect.","e":"Your new allies distrust you, and it rubs off on those around you."},"v20-blood-hunted":{"f":"You are under a Blood Hunt.","e":"At four points, your home city wants you dead; at six, the whole Camarilla. Camarilla only."},"v20-laughingstock":{"f":"The Harpies have made you their favourite joke.","e":"+2 difficulty on Social rolls in Elysium, +1 elsewhere, and +2 to intimidate or Dominate anyone who knows the stories. Camarilla only."},"v20-red-list":{"f":"You are on, or about to be added to, the Red List.","e":"Camarilla vampires attack you on sight, or call for help."},"v20-deceptive-aura":{"f":"Your aura is bright and colourful, like a living person’s.","e":"Anyone reading your aura sees a mortal."},"v20-healing-touch":{"f":"You close bite wounds with a touch.","e":"Seal feeding wounds by touch instead of licking them."},"v20-hidden-diablerie":{"f":"Your aura hides your crimes.","e":"The black streaks of diablerie never show in your aura."},"v20-lucky":{"f":"You were born lucky, or the Devil looks after his own.","e":"Three times per story, reroll a failed roll (even a botch), once per roll."},"v20-spirit-mentor":{"f":"A ghost watches over you and guides you.","e":"Call on it for help and advice in hard moments; the Storyteller decides who it is and what it can do."},"v20-true-love":{"f":"You found your true love, a mortal who keeps you going.","e":"One automatic success on all Willpower rolls (only a botch die cancels it), but they may need protecting."},"v20-additional-discipline":{"f":"One more Discipline comes to you as easily as your clan’s.","e":"Learn one extra Discipline at in-clan cost (Storyteller approval). Once only; not for Caitiff."},"v20-nine-lives":{"f":"Fate keeps pulling you back from the brink.","e":"When a roll would destroy you, reroll it; each reroll uses one of your nine lives."},"v20-true-faith":{"f":"You believe in God with your whole being.","e":"Start with one dot of True Faith: one die per dot to Willpower and Virtue rolls, and miracles at the Storyteller’s discretion. Needs Humanity 9; losing Humanity loses it."},"v20-cast-no-reflection":{"f":"Like the vampires of legend, you have no reflection.","e":"Mirrors and cameras show nothing, which makes passing as human hard and gets you mistaken for Lasombra."},"v20-cold-breeze":{"f":"A chill wind follows you everywhere.","e":"+1 difficulty on Social rolls with mortals, and you’re obviously supernatural."},"v20-touch-of-frost":{"f":"Life withers around you.","e":"Plants wilt as you pass and die at your touch, and your touch drains heat from the living."},"v20-cursed":{"f":"A supernatural curse hangs over you.","e":"The more points, the deeper the curse.","lv":{"1":"Betray a secret and it comes back to harm you.","2":"You stutter when you try to describe what you saw or heard.","3":"Tools break or fail when you use them.","4":"You turn those you love or admire into enemies.","5":"Every triumph eventually turns sour or fails."}},"v20-beacon-of-the-unholy":{"f":"You radiate evil.","e":"Clergy and the devout instinctively know something is wrong with you."},"v20-deathsight":{"f":"You see the world as a rotting corpse.","e":"−2 difficulty to resist Appearance-based rolls, but +2 to Perception and +1 to Social rolls."},"v20-eerie-presence":{"f":"Mortals sense the dead thing in you.","e":"Social rolls with mortals are at +2 difficulty."},"v20-lord-of-the-flies":{"f":"Flies swarm around you wherever you go.","e":"+1 difficulty to Social rolls when it matters and +2 to Stealth."},"v20-haunted":{"f":"An angry ghost, likely one of your first victims, haunts you.","e":"It hinders you, especially when you feed, and torments those around you."},"v20-grip-of-the-damned":{"f":"Your Kiss brings terror and pain, not bliss.","e":"Victims fight and scream: you must grapple them to keep feeding. Not for Giovanni."},"v20-dark-fate":{"f":"You are doomed to Final Death, or worse.","e":"It will happen during the chronicle. When visions of it come, spend a Willpower or lose a die on everything that night."},"v20-light-sensitive":{"f":"Even moonlight hurts you.","e":"Sunlight does double damage, direct moonlight burns like the sun, and bright light hurts your eyes. Not for Setites and their kin."},"dgr-2b70VAegIg10GcQJ":{"f":"Your domitor’s Blood can’t pass on its curse to you.","e":"You are immune to the clan banes in the Blood you drink. Refunded if you’re Embraced."},"dgr-320ZxBZUGQeVnafL":{"f":"Your body doesn’t snap back to how it looked when you died.","e":"Keep new haircuts, tattoos and piercings; you can remove them like Aggravated damage. Only at Blood Potency 1 or lower."},"dgr-3iEVgtfqiYC3DCCL":{"f":"You’ve hidden for so long you’re forgetting who you are.","e":"Lose one die on Degeneration tests (minimum 1)."},"dgr-3vN5uxKwK2fTHALN":{"f":"You remember everything you see and hear.","e":"Commit documents and conversations to memory perfectly; under heavy distraction roll Resolve + Awareness (Difficulty 2)."},"dgr-5ASFgUz04XAyjjMQ":{"f":"An injury from your Embrace, or from life, never healed.","e":"One fewer Health box."},"dgr-5LFhEFubrM2cdFVU":{"f":"You serve a demon as its thrall.","e":"Trade faith and service for its favours; up to five dots spread between its power and its goodwill. Not for ghosts."},"dgr-6cd4abzxgRwmUK5k":{"f":"Your aura is pale, like a vampire’s.","e":"Aura-reading powers see you as one of the Kindred unless they score 5 or more margins."},"dgr-6lZB6OUmW29N0vyU":{"f":"You can’t take much pain.","e":"You become Impaired once your damage equals your Stamina."},"dgr-7VKxsdLg4eJKfCeZ":{"f":"You cannot hear.","e":"Lose three dice on rolls involving hearing; some uses of Dominate don’t work on you."},"dgr-7iAHHyWMkdQ7mXir":{"f":"Poisons don’t work on you.","e":"You are immune to mortal poisons, toxins and drugs. Not with Substance Use Merits or Flaws."},"dgr-8sPHOOIFw2kwggRJ":{"f":"Your Beast refuses the leash.","e":"Failing to Ride the Wave in frenzy deals two Aggravated Willpower damage."},"dgr-9Zj8X3X08g15L8I9":{"f":"Your day-sleep is full of half-remembered horrors.","e":"You sweat blood as you rest: make two Rouse Checks on waking instead of one."},"dgr-9dJ0dqzMoRKs5XSi":{"f":"Madness has taken root in you.","e":"Each dot gives two triggers for a Derangement of your choice (up to five dots). Take it more than once for more Derangements."},"dgr-AlUuUXpHtGiON4Qm":{"f":"Serpentis is changing your skin.","e":"You wake each night with scales or feathers; scrubbing them off deals two Superficial damage."},"dgr-ApJkJouBo1IZtMaC":{"f":"Commanding minds has made ordinary conversation hard.","e":"You can’t spend Willpower to reroll Social tests."},"dgr-BjKqVJOrq1iaup4y":{"f":"Something common fills you with terror.","e":"When you meet it, make a Difficulty 2 fear frenzy test."},"dgr-CBRV7msvIDrSnmYx":{"f":"You can sense and speak with ghosts.","e":"Hear, speak to and coax spirits and ghosts into your presence, and ask their help, always for a price."},"dgr-ChmEV0Ne0k62eIVW":{"f":"Your soul no longer makes Faith on its own.","e":"You must find other ways to fuel infernal gifts. Vampires have this by default."},"dgr-Ea2a1mprgkiXDnX0":{"f":"You serve a god, and your god answers.","e":"Once per session, pray for a turn to gain temporary Willpower equal to half the dots, to reroll or fuel powers."},"dgr-FUp4EMrcJjHtEBLp":{"f":"Your shadow moves on its own.","e":"Lose three dice on non-threatening dealings with mortals wherever your shadow can be seen."},"dgr-FVlYGVvrpa7V1uZ5":{"f":"You sense the hidden patterns of the world.","e":"Use Awareness to notice wards, Obfuscate, Presence and illusions such as Chimerstry."},"dgr-FYu1PWlpi3gS54dl":{"f":"You trust yourself too much to work with others.","e":"Taking part in or benefiting from teamwork costs one Superficial Willpower."},"dgr-G0EIf5oV49Dd8bf1":{"f":"Nothing breaks your focus.","e":"Ignore penalties from distractions such as noise or awkward positions."},"dgr-GABaCv8DI9qYKRLL":{"f":"When you feed, the victim’s Blood floods your mind.","e":"For a scene after feeding, lose two dice from one kind of pool (by your Quietus path). Willpower ignores it for a turn."},"dgr-Hqgaotec0c4j0w2w":{"f":"You’ve grown retractable fangs like a vampire.","e":"Bite attacks deal two Aggravated damage, even to supernatural beings, after a called shot. No Embrace."},"dgr-INiT7w8ydJ9H0lty":{"f":"You cannot see.","e":"Lose three dice on sight-based rolls and most combat rolls. Auspex still works through other senses."},"dgr-J629mvt4cFmu7UzH":{"f":"You know an old charm or curse passed down by word of mouth.","e":"Each purchase teaches one ritual of a level equal to the dots, cast as hedge magic. Mortals only."},"dgr-K6Iq4Z3Dxd8bL6JW":{"f":"You’ve flown so long the ground feels like a cage.","e":"Frenzy difficulties +1 in enclosed spaces, but your Flight counts as one dot higher."},"dgr-MHU4xfTrqNInuIjy":{"f":"You cannot speak.","e":"You communicate in writing or sign language only."},"dgr-MaTRWOLrbLYb5lNL":{"f":"Your body is old and frail.","e":"Lose one die on Physical rolls. Mortals only; ghouling removes the penalty."},"dgr-NbZEGz0xfYH40QQ9":{"f":"You were a revenant before your Embrace, and you kept the family gifts.","e":"Use your old family’s loresheet and Disciplines in place of your clan’s, but you also keep its Family Affliction."},"dgr-Pa2IURl11noaWn5I":{"f":"You are enormous.","e":"One extra Health box; Strength counts one higher for feats of strength, plus a die to push, force doors or stay standing."},"dgr-QKKVd9ON7TUmxxJl":{"f":"Your legs are badly damaged.","e":"You walk at a quarter speed and can’t run; lose three dice on anything using your legs."},"dgr-RPw4kyeUrs25j9nc":{"f":"Potence feeds your Beast.","e":"If a Rouse Check for Potence fails, test for fury frenzy at once."},"dgr-RQp4ve5WLYPn8rvo":{"f":"You bear a disfiguring skin disease from life.","e":"No Looks Merits; you are feared and shunned. At three dots you can pass it on to those you feed from."},"dgr-SDOJrcO4vvBDqBmw":{"f":"You are very short, four feet or less.","e":"Adult-sized objects are hard to use, and you run at half speed."},"dgr-SY13wc2m0fCLdTld":{"f":"The fae Blood is changing you.","e":"Gain folkloric constraints equal to your Mytherceria rating."},"dgr-T86Oeq4LcJNUzWpd":{"f":"Your reshaped flesh has a mind of its own.","e":"Each night spend a Rouse Check to calm it, or lose two dice on Charisma and seduction and risk the Masquerade."},"dgr-TIAOoLdWT4RbaGJU":{"f":"You can’t always tell your illusions from the world.","e":"Lose dice on Awareness and perception rolls equal to half your Chimerstry, rounded up."},"dgr-UDbEodrMVICYYDNe":{"f":"Your psychic gifts work even when your body and mind don’t.","e":"Mental Impairment doesn’t affect Psychic Numina; when Incapacitated, spend Willpower once per scene for a last half-pool power."},"dgr-Y0wtOxMoXsLmNA7o":{"f":"You have plenty of practical wisdom.","e":"The Storyteller warns you before you do something foolish."},"dgr-YcRs6gud6ZY1w6PQ":{"f":"Servants beyond the ordinary: beasts, spirits, ghosts, constructs and familiars.","e":"Dark Gifts retainer types, each with its own dot ladder: animal companions, bound spirits, ghosts, necromantic constructs, revenants and familiars."},"dgr-Z1JrqeKESr10TwUK":{"f":"You feel when your domitor needs you.","e":"You sense when your regnant is in danger or needs you at once. No telepathy."},"dgr-ZWjKLfcBsoKOxtap":{"f":"You’ve grown fangs like a vampire.","e":"Lose one die on Social pools with ordinary mortals."},"dgr-Zgsz2eeq52pVHzxw":{"f":"Speed burns through your body.","e":"When a Rouse Check for Celerity fails, take one Aggravated damage as your body visibly ages."},"dgr-ZnZREcVndE1eYJZY":{"f":"The music never stops, and you must let it out.","e":"Lose three dice on Social Skill tests unless you’re using performance, poetry or music."},"dgr-Zv7NR0STOKWG7qYD":{"f":"You look decades older than you are.","e":"One fewer Health box."},"dgr-aVrW5niH9DKwTJb4":{"f":"You remember nothing of your past.","e":"The Storyteller decides who you were, and that past may come back to haunt you."},"dgr-bS0ekyJMMSkzljmX":{"f":"Daimonion shows you the suffering in everything.","e":"Fulfilling your Desire restores no Willpower."},"dgr-bsaWb3Y8N3YECsQC":{"f":"Your heart isn’t where it should be.","e":"Attackers need one extra success to target your heart."},"dgr-cYt018AF33itz1J0":{"f":"You always hunt the same places.","e":"Hunting outside your predator type is at +2 Difficulty."},"dgr-eRbY913Bd17sXl7y":{"f":"Learning magic comes naturally to you.","e":"Halve (round up) the thresholds for learning or creating new magic."},"dgr-fPpCnWuj8Ocs6NGk":{"f":"You feel the movement of the sun, moon and stars.","e":"Know the time to sunrise or sunset within a minute or two, and track the moon’s phases."},"dgr-fVgu6c0IF0BHBOxe":{"f":"Your body resists change.","e":"When a Rouse Check for Protean fails, part of the change sticks uselessly until day-sleep or until you cut it off (one Aggravated)."},"dgr-flFHJ5yI9xtiMekp":{"f":"You can’t stand not being adored.","e":"When a Presence power fails or messes up, make a Difficulty 2 fury frenzy test."},"dgr-hEvodBxUslAfPhTv":{"f":"A place of power that resonates with your sorcery.","e":"Inside it your magic gets bonus dice and botches carry no magical risk.","lv":{"1":"Pantry-sized: +1 die to use magic there.","2":"A small room or copse: +1 die.","3":"A workshop and side room: +2 dice.","4":"A cottage or suite: +2 dice and −1 casting Difficulty.","5":"A mansion, castle wing or forest: as above, and you sense intruders."}},"dgr-hyoVzOl8UQbn33yI":{"f":"You separate facts from feelings.","e":"Add a die to Insight and to reading emotions, but lose a die on Charisma and Persuasion rolls."},"dgr-iP9U3AEUhpklOye0":{"f":"Your will is iron.","e":"Once per session add two dice to resist mind control, and roll Wits + Awareness to notice it. Lost if you learn such powers."},"dgr-jRhXUJa0uU4rMRZ9":{"f":"Your fangs never retract.","e":"Lose one die on Social pools with ordinary mortals. Not for Nagaraja."},"dgr-kEUaipV8iq5eUvKo":{"f":"Magic just doesn’t click for you.","e":"+1 Difficulty to all casting tests. Only if you have sorcery or in-clan Blood Sorcery."},"dgr-mHaZ7gNVFlWADT8r":{"f":"Thanatosis’ decay is seeping into your own flesh.","e":"Your Strength counts as two lower (minimum 1); a Rouse Check renews you for a scene."},"dgr-nPBsKJHsb4ldcVHe":{"f":"Psychic powers struggle to touch you.","e":"Once per session add two dice to resist psychic powers or Auspex, and roll Wits + Awareness to notice scrying. Lost if you learn such powers."},"dgr-o60I0jBsQyNSWDDr":{"f":"You barely feel pain.","e":"When Impaired by Health damage, take −1 instead of −2."},"dgr-oHMFqWJ9jlu9gUDw":{"f":"Demon blood runs in your family.","e":"Gain Arcana equal to the dots and two dots of Divinity for demonic powers, and count as two Status higher among infernal beings. Faith and aura reading can spot you."},"dgr-qNU1P3u83s1JaOvD":{"f":"Magic has little effect on you, and you on it.","e":"Once per session add two dice to resist any magic, and roll Wits + Awareness to notice it. Lost if you learn sorcery."},"dgr-qjNNHOxZ5fg0IhUE":{"f":"You read omens and signs.","e":"Spot and interpret omens the Storyteller sends; once per session force one, and add up to three dice from it to a roll."},"dgr-r1lxBtoA5I4wlTAT":{"f":"You have a score to settle.","e":"In the presence of the target of your revenge, make a Difficulty 3 fury frenzy test."},"dgr-sz3llTVzAfYc2gqB":{"f":"Serving a demon never stained your soul.","e":"No degeneration checks for your thralldom, until you gain a permanent dot of Torment. Thralls only."},"dgr-t5jtTwArs4lLOHE1":{"f":"The Embrace didn’t take your gift for magic.","e":"One dot: Blood Sorcery needs no Resonance to advance. Two dots: it also costs at most 6 × the new level."},"dgr-u0f7dWtv0vzteN9R":{"f":"Both hands work equally well.","e":"No penalty for using your off hand or two weapons."},"dgr-ujXEhotbvpwDbjpF":{"f":"Half your mind drifts in the spirit world.","e":"Lose three dice on rolls to perceive things in the material world."},"dgr-vgVTkXS3rxs75gI6":{"f":"Your sense of morality is splintering.","e":"On Humanity you need two Touchstones per Conviction; on a Road with Conviction you can hold only one Ethic."},"dgr-vjB6yIVAw4n6uk1b":{"f":"Vivid nightmares haunt your day-sleep.","e":"You recover less Superficial Willpower at the start of each session."},"dgr-wL9N8DwyyQAsbYCa":{"f":"You rarely fall ill.","e":"Add two dice to resist disease, natural or supernatural."},"dgr-wfj4QcDS9zo5vgkG":{"f":"You once made a pact with a demon, and now you’re on your own.","e":"Two dots: your master is gone but may return. Four dots: you are truly free, but can’t gain new Arcana. Start with one Divinity."},"dgr-xVALW1mvQOOdDo5a":{"f":"Animals don’t fear you.","e":"One dot: one species treats you like a human and you get a die on Animal Ken with it. Two dots: all ordinary animals."},"dgr-xgNrZdSC8YCEGPls":{"f":"You know rituals to summon and bind demons, and their true names.","e":"Only mortals can perform them, so vampires need a human to do the work. Up to six dots, at creation only."},"dgr-yWte0ruLLNxZrQyD":{"f":"Time pushes back against you.","e":"When a Rouse Check for Temporis fails, take one Aggravated damage as your body ages."},"dgr-ywywZbDiqkya88qA":{"f":"Your first domitor’s curse never left you.","e":"Your first ghoul bane is permanent; a new domitor adds a second one."},"dgr-zZK6nN3ZW75gFlLC":{"f":"Your wounds heal, but keep showing.","e":"Injuries stay visible until day-sleep even after you mend them, risking the Masquerade."},"dgr-zk1ZR5L9NmDm3TQh":{"f":"A fleshcrafter has reshaped your body.","e":"Each dot is a dot of the sculptor’s Vicissitude, spent as Attribute dots on modifications."}};
